 * Splits the raw standard input for the CLI into its three documents.
 */

/**
 * Splits `text` on newlines, drops the empty tail a trailing newline leaves,
 * and separates the resulting lines into three documents at `%%%` markers.
 * Throws an `Error` when the input does not hold exactly three parts.
 *
 * @param {string} text
 * @returns {{ mine: string[], base: string[], theirs: string[] }}
 */
export function parseInput(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  const parts = [[]]
  for (const line of lines) {
    if (line === '%%%') {
      parts.push([])
    } else {
      parts[parts.length - 1].push(line)
    }
  }

  if (parts.length !== 3) {
    throw new Error('expected three parts separated by %%%')
  }

  const [mine, base, theirs] = parts
  return { mine, base, theirs }
}
"}

