{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e12-self-review-sonnet-t5t6-20260927T000002Z/cell-MIcMdZ/src/diff.js","content":"/**
 * Computes the changes between one side of a merge and the base it derives
 * from, using a longest common subsequence over whole lines.
 */

/**
 * @typedef {Object} Change
 * @property {number} baseStart inclusive start index into `base`
 * @property {number} baseEnd exclusive end index into `base`
 * @property {number} sideStart inclusive start index into `side`
 * @property {number} sideEnd exclusive end index into `side`
 */

/**
 * Finds the changes needed to turn `base` into `side`, described as runs of
 * base lines replaced by runs of side lines. Ties in the longest common
 * subsequence are broken by preferring the match whose lines come earliest:
 * walking both documents from the start, a mismatch advances whichever side
 * keeps the longer (or, on a tie, the base's) remaining subsequence.
 *
 * @param {string[]} base
 * @param {string[]} side
 * @returns {Change[]}
 */
export function computeChanges(base, side) {
  const m = base.length
  const n = side.length

  // dp[i][j] holds the length of the longest common subsequence of
  // base[i:] and side[j:].
  const dp = new Array(m + 1)
  for (let i = 0; i <= m; i++) {
    dp[i] = new Int32Array(n + 1)
  }
  for (let i = m - 1; i >= 0; i--) {
    for (let j = n - 1; j >= 0; j--) {
      dp[i][j] = base[i] === side[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1])
    }
  }

  const changes = []
  let i = 0
  let j = 0
  let changeBaseStart = 0
  let changeSideStart = 0
  let inChange = false

  const flush = (baseEnd, sideEnd) => {
    if (inChange) {
      changes.push({ baseStart: changeBaseStart, baseEnd, sideStart: changeSideStart, sideEnd })
      inChange = false
    }
  }

  while (i < m && j < n) {
    if (base[i] === side[j]) {
      flush(i, j)
      i++
      j++
    } else {
      if (!inChange) {
        inChange = true
        changeBaseStart = i
        changeSideStart = j
      }
      if (dp[i + 1][j] >= dp[i][j + 1]) {
        i++
      } else {
        j++
      }
    }
  }

  if (!inChange && (i < m || j < n)) {
    inChange = true
    changeBaseStart = i
    changeSideStart = j
  }
  if (inChange) {
    flush(m, n)
  }

  return changes
}
"}

