{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e12-self-review-sonnet-t5t6-20260927T000002Z/cell-MIcMdZ/src/regions.js","content":"/**
 * Groups the changes from both sides of a merge into regions and resolves
 * each one.
 */

import { computeChanges } from './diff.js'

/**
 * @typedef {Object} StableRegion
 * @property {'stable'} kind
 * @property {string[]} lines
 *
 * @typedef {Object} ResolvedRegion
 * @property {'mine' | 'theirs' | 'both'} kind
 * @property {string[]} lines
 *
 * @typedef {Object} ConflictRegion
 * @property {'conflict'} kind
 * @property {string[]} mine
 * @property {string[]} base
 * @property {string[]} theirs
 *
 * @typedef {StableRegion | ResolvedRegion | ConflictRegion} Region
 */

function linesEqual(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) {
    if (a[i] !== b[i]) return false
  }
  return true
}

/**
 * Runs one side's own changes within a region through the moved-back,
 * moved-forward rule and returns that side's replacement lines for the
 * region.
 *
 * @param {import('./diff.js').Change[]} ownChanges changes for this side, in base order
 * @param {string[]} base the whole base document
 * @param {string[]} side the whole side document
 * @param {number} regionStart
 * @param {number} regionEnd
 * @returns {string[]}
 */
function sideLinesForRegion(ownChanges, base, side, regionStart, regionEnd) {
