{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e12-self-review-sonnet-t5t6-20260927T000002Z/cell-MIcMdZ/src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js merge`, `node src/cli.js merge2` and
 * `node src/cli.js regions` each read three documents from standard input and
 * report the three-way merge of the second into the first and the third.
 */

import { parseInput } from './parse.js'
import { computeRegions } from './regions.js'

const MODES = new Set(['merge', 'merge2', 'regions'])

function readStdin() {
  const chunks = []
  const fd = 0
  const buffer = Buffer.alloc(65536)
  const fs = require('node:fs')
  for (;;) {
    let bytesRead
    try {
      bytesRead = fs.readSync(fd, buffer, 0, buffer.length, null)
    } catch (error) {
      if (error.code === 'EAGAIN') continue
      if (error.code === 'EOF') break
      throw error
    }
    if (bytesRead === 0) break
    chunks.push(Buffer.from(buffer.subarray(0, bytesRead)))
  }
  return Buffer.concat(chunks).toString('utf8')
}

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function renderMerge(regions, withBase) {
  const out = []
  let conflict = false
  for (const region of regions) {
    if (region.kind === 'conflict') {
      conflict = true
      out.push('<<<<<<< mine', ...region.mine)
      if (withBase) {
        out.push('||||||| base', ...region.base)
      }
      out.push('=======', ...region.theirs, '>>>>>>> theirs')
    } else {
      out.push(...region.lines)
    }
  }
  return { text: out.length > 0 ? out.join('\n') + '\n' : '', conflict }
}

function renderRegions(regions) {
  const out = []
  let conflict = false
  for (const region of regions) {
    if (region.kind === 'conflict') {
      conflict = true
      out.push(`conflict mine=${region.mine.length} base=${region.base.length} theirs=${region.theirs.length}`)
    } else {
      out.push(`${region.kind} ${region.lines.length}`)
    }
  }
  return { text: out.length > 0 ? out.join('\n') + '\n' : '', conflict }
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || !MODES.has(args[0])) {
    fail('usage: cli.js merge|merge2|regions')
    return
  }
  const mode = args[0]

  const input = readStdin()
  let mine, base, theirs
  try {
    ;({ mine, base, theirs } = parseInput(input))
  } catch (error) {
    fail(error.message)
    return
  }

  const regions = computeRegions(mine, base, theirs)

  let result
  if (mode === 'merge') {
    result = renderMerge(regions, true)
  } else if (mode === 'merge2') {
    result = renderMerge(regions, false)
  } else {
    result = renderRegions(regions)
  }

  process.stdout.write(result.text)
  process.exit(result.conflict ? 1 : 0)
}

main()
"}

